    ('VH-LUD037', date '2026-10-09', 'Radiator not heating', 'Communal lounge', 'heating', 'routine', 'Contractor A – Plumbing & Heating', date '2026-11-06', null, 'assigned'),
    ('VH-CLA011', date '2026-10-09', 'Blocked shower drain', 'Kitchen', 'plumbing', 'routine', 'Contractor A – Plumbing & Heating', date '2026-11-06', null, 'assigned')
  ) t(pref, reported, title, location, category, urgency, contractor, due, completed, status)
  loop
    pid := (select id from properties where company_id = co and ref = r.pref);
    continue when pid is null or exists (select 1 from repairs where property_id = pid and title = r.title and reported_on = r.reported);
    insert into repairs (company_id, property_id, title, urgency, status, contractor, due_on, completed_on, closed_at, reported_by, reported_on,
                         category, location, notes, created_at, updated_at)
    values (co, pid, r.title, r.urgency, r.status, r.contractor, r.due, r.completed,
            case when r.status = 'closed' then (r.completed::timestamp + interval '12 hours') at time zone 'Europe/London' end, who, r.reported,
            r.category, r.location, 'Added on 4 Nov 2026 from Valor''s 2026 repairs register.'
              || case when r.status = 'closed' then ' Recorded there as completed; not verified in the Hub.' else '' end,
            r.reported::timestamp at time zone 'Europe/London', now());
  end loop;
end $$;
